<?php
namespace App\Http\Controllers\Demo\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\BlockedTimeRequest; use App\Models\BlockedTime; use Carbon\CarbonImmutable; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class BlockedTimeController extends Controller { private function find(int$id):BlockedTime{return BlockedTime::where('shop_id',auth()->user()->shop_id)->findOrFail($id);} public function index():View{$shop=auth()->user()->shop;return view('demo.admin.blocks.index',['blocks'=>BlockedTime::with('staff')->where('shop_id',$shop->id)->orderByDesc('starts_at')->get(),'staffs'=>$shop->staffs()->where('is_active',true)->get()]);} public function store(BlockedTimeRequest$r):RedirectResponse{$data=$r->validated();$timezone=auth()->user()->shop->timezone;$data['starts_at']=CarbonImmutable::parse($data['starts_at'],$timezone)->utc();$data['ends_at']=CarbonImmutable::parse($data['ends_at'],$timezone)->utc();auth()->user()->shop->blockedTimes()->create($data);return back()->with('success','予約不可時間を追加しました。');} public function destroy(int$block):RedirectResponse{$this->find($block)->delete();return back()->with('success','予約不可時間を削除しました。');} }
